import axios from "axios";

const API_URL =
  "https://script.google.com/macros/s/AKfycbztxeWYYCHTe5c57_keeFVtp9JiQIqlwFdDBwL3XU2eKkVKFcfMSqg09hVmKpw1ewVAwQ/exec";
const headers = new Headers();
headers.append("Content-Type", "application/json");

// 讀取清冊
export const getMembersList = async () => {
  const payload = JSON.stringify({
    route_type: "get_users_form",
  });

  const response = await axios.post(API_URL, payload, headers);

  // 你的原始 code 裡 response 是包在 data[0].result 裡面
  const parsedResult = JSON.parse(response.data[0]?.result || "{}");
  return parsedResult; // 直接回傳 { headers, rows }
};

// 讀取月統計
export const getMonthlyStats = async () => {
  const payload = JSON.stringify({
    route_type: "month_count",
  });

  const response = await axios.post(API_URL, payload, headers);
  const parsedResult = JSON.parse(response.data?.result || "{}");
  return parsedResult;
};

// 讀取使用者
export const getUserList = async () => {
  const response = await axios.post(
    API_URL,
    JSON.stringify({
      route_type: "get_select_list",
      query_key: "get_users",
    }),
    headers
  );
  return response.data[0]?.result || [];
};

