import React, { useState, useEffect } from "react";
import { getUserList, createActivity } from "../../utils/api";
import toast from "react-hot-toast";

const ActivityForm = () => {
  const [activityName, setActivityName] = useState("");
  const [activityLocation, setActivityLocation] = useState("");
  const [organizer, setOrganizer] = useState("");
  const [activityTime, setActivityTime] = useState("");
  const [organizers, setOrganizers] = useState([]);
  const [loading, setLoading] = useState(false);
  const [selectLoading, setSelectLoading] = useState(true);

  useEffect(() => {
    async function fetchData() {
      try {
        const data = await getUserList();
        setOrganizers([{ label: "請選擇", value: "" }, ...data]);
      } catch (err) {
        toast.error("載入使用者失敗");
      } finally {
        setSelectLoading(false);
      }
    }
    fetchData();
  }, []);

  const handleSubmit = async () => {
    if (!activityTime || !organizer || !activityName) {
      toast.error("請完整填寫資料");
      return;
    }
    try {
      setLoading(true);
      await createActivity({
        activity_date: activityTime,
        user_id: organizer,
        activity_place: activityLocation,
        activity_name: activityName,
        activity_type: "in-person",
      });

      toast.success("新增成功！");
      setActivityName("");
      setActivityLocation("");
      setActivityTime("");
      setOrganizer("");
    } catch (err) {
      console.error(err);
      toast.error("新增失敗");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-white bg-opacity-20 backdrop-blur-lg rounded-lg p-6 shadow-lg">
      <h2 className="text-xl font-bold mb-4">新增活動</h2>
      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-4 mb-4">
        <div>
          <label className="block mb-1 text-sm">活動日期</label>
          <input
            type="date"
            className="p-2 rounded w-full text-black"
            value={activityTime}
            onChange={(e) => setActivityTime(e.target.value)}
          />
        </div>
        <div>
          <label className="block mb-1 text-sm">揪團者</label>
          <select
            className="p-2 rounded w-full text-black"
            value={organizer}
            onChange={(e) => setOrganizer(e.target.value)}
            disabled={selectLoading}
          >
            {selectLoading ? (
              <option>載入中...</option>
            ) : (
              organizers.map((opt) => (
                <option key={opt.value} value={opt.value}>
                  {opt.label}
                </option>
              ))
            )}
          </select>
        </div>
        <div>
          <label className="block mb-1 text-sm">活動名稱</label>
          <input
            type="text"
            className="p-2 rounded w-full text-black"
            value={activityName}
            onChange={(e) => setActivityName(e.target.value)}
          />
        </div>
        <div>
          <label className="block mb-1 text-sm">活動地點</label>
          <input
            type="text"
            className="p-2 rounded w-full text-black"
            value={activityLocation}
            onChange={(e) => setActivityLocation(e.target.value)}
          />
        </div>
      </div>
      <div className="mt-4">
        <button
          className={`bg-blue-500 px-4 py-2 rounded text-white w-full sm:w-auto ${
            loading ? "opacity-50" : ""
          }`}
          onClick={handleSubmit}
          disabled={loading}
        >
          {loading ? "處理中..." : "新增"}
        </button>
      </div>
    </div>
  );
};

export default ActivityForm;
