import React, {
  useEffect,
  useState,
  useCallback,
  useRef,
  useMemo,
} from "react";
import axios from "axios";
import { toast } from "react-hot-toast";
import styles from "./LeaderBoard.module.css";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faRotate } from "@fortawesome/free-solid-svg-icons";

const LeaderBoard = () => {
  const [data, setData] = useState([]);
  const [timestamp, setTimestamp] = useState(null);
  const [loading, setLoading] = useState(false);
  const viewportHeight = window.innerHeight;

  const clickCountRef = useRef(0);
  const CACHED_LEADERBOARD_DATA = "leaderboardData";
  const CACHED_LEADERBOARD_TIMESTAMP = "leaderboardTimestamp";
  const REFRESH_INTERVAL = 300000; // 5 minutes

  const raw = JSON.stringify({
    query_type: "rank",
  });

  const myHeaders = useMemo(() => {
    const headers = new Headers();
    headers.append("Content-Type", "application/json");
    return headers;
  }, []); // 依賴為空陣列，確保只在首次渲染時創建

  const fetchLeaderBoardData = useCallback(async () => {
    setLoading(true);
    try {
      const response = await axios.post(
        "https://script.google.com/macros/s/AKfycbx3mjWYbtJwLx7h3qnkFBjaSwI1Xd6_JpCyA0_TIQP9QIHXSkk_zh4u_gPdhCoVwjmnGA/exec",
        raw,
        myHeaders
      );

      const result = response.data;
      setData(result);
      localStorage.setItem(CACHED_LEADERBOARD_DATA, JSON.stringify(result));
      localStorage.setItem(CACHED_LEADERBOARD_TIMESTAMP, Date.now().toString());
      setTimestamp(new Date());
    } catch (error) {
      console.error("Error fetching leaderboard data:", error);
      toast.error("資料取得失敗");
    } finally {
      setLoading(false);
    }
  }, [raw, myHeaders]); // 依賴包括 raw 和 myHeaders

  useEffect(() => {
    const cachedData = localStorage.getItem(CACHED_LEADERBOARD_DATA);
    const cachedTimestamp = localStorage.getItem(CACHED_LEADERBOARD_TIMESTAMP);

    if (cachedData && cachedTimestamp) {
      setData(JSON.parse(cachedData));
      setTimestamp(new Date(parseInt(cachedTimestamp)));
    } else {
      fetchLeaderBoardData();
    }
  }, [fetchLeaderBoardData]); // 依賴 fetchLeaderboardData

  const handleRefresh = () => {
    const cachedTimestamp = localStorage.getItem(CACHED_LEADERBOARD_TIMESTAMP);
    const currentTime = Date.now();

    if (
      !cachedTimestamp ||
      currentTime - parseInt(cachedTimestamp) > REFRESH_INTERVAL
    ) {
      fetchLeaderBoardData();
      clickCountRef.current = 0;
    } else {
      clickCountRef.current += 1;
      if (clickCountRef.current <= 3) {
        toast.error("刷新次數過於頻繁，請稍後再試。");
      } else if (clickCountRef.current <= 6) {
        toast.error("就說了稍後再試");
      } else {
        toast.error("＾＿＾");
      }
    }
  };

  const getRankClass = (rank) => {
    switch (rank) {
      case 1:
        return styles.bgGold;
      case 2:
        return styles.bgSilver;
      case 3:
        return styles.bgBronze;
      default:
        return styles.bgGray;
    }
  };

  const getArrow = (changeType) => {
    const arrowStyle =
      "text-2xl font-bold flex items-center justify-center bg-black bg-opacity-60 w-8 h-8 rounded-full shadow-md";
    switch (changeType) {
      case -1:
        return "";
      case "down":
        return <span className={`${arrowStyle} text-red-500`}>↓</span>;
      case "up":
        return <span className={`${arrowStyle} text-green-500`}>↑</span>;
      default:
        return <span className={`${arrowStyle}`}>-</span>;
    }
  };

  const formatTimestamp = (date) => (date ? date.toLocaleString() : "尚未更新");
  const rankList = data[0]?.result || [];

  const Skeleton = () => (
    <div className="animate-pulse space-y-4">
      {Array.from({ length: 10 }).map((_, index) => (
        <div key={index} className="h-12 bg-gray-700 rounded-lg shadow-lg" />
      ))}
    </div>
  );

  return (
    <div
      className="relative"
      style={{
        height: `${viewportHeight}px`,
        backgroundImage: `url(${process.env.PUBLIC_URL}/atlantis-background.png)`,
        backgroundSize: "cover",
        backgroundPosition: "center",
      }}
    >
      <div className="absolute inset-0 bg-black bg-opacity-60 flex justify-center items-center">
        <div className="max-w-5xl w-full p-6 text-white">
          <h1 className="text-2xl font-bold text-center mb-3">排行榜</h1>
          <p className="text-center mb-4 text-xs">
            數據更新時間為：{formatTimestamp(timestamp)}{" "}
            <button onClick={handleRefresh} className="ml-2">
              <FontAwesomeIcon
                className={`text-xl text-white ${
                  loading ? "animate-spin" : ""
                }`}
                icon={faRotate}
              />
            </button>
          </p>
          <div
            className="overflow-y-auto space-y-4"
            style={{ maxHeight: `${viewportHeight * 0.8}px` }}
          >
            <div
              className={`flex text-sm justify-between items-center p-2 rounded-lg shadow-lg`}
            >
              <span className="flex-shrink-0 w-16 font-bold text-center">
                排名
              </span>
              <span className="flex-1 text-center overflow-hidden whitespace-nowrap text-ellipsis">
                大名
              </span>
              <span className="flex-shrink-0 w-12 text-center">
                上月
                <br />
                發話
              </span>
              <span className="flex-shrink-0 w-12 text-center">
                本月
                <br />
                發話
              </span>
            </div>
            {loading ? (
              <Skeleton />
            ) : (
              rankList.map((user, index) => (
                <div
                  key={`${user.username}-${index}`}
                  className={`flex text-sm justify-between items-center p-2 rounded-lg shadow-lg ${getRankClass(
                    user.rank
                  )}`}
                >
                  <span className="flex-shrink-0 w-8 font-bold text-center">
                    {user.rank}
                  </span>
                  <span className="flex-shrink-0 w-8">
                    {getArrow(user.change_type)}
                  </span>
                  <span className="flex-1 text-center overflow-hidden whitespace-nowrap text-ellipsis px-2">
                    {user.name}
                  </span>
                  <span className="flex-shrink-0 w-12 text-center">
                    {user.last_count}
                  </span>
                  <span className="flex-shrink-0 w-12 text-center">
                    {user.this_count}
                  </span>
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default LeaderBoard;
