import React, { useState } from "react";
import { Link } from "react-router-dom";
// import Navbar from "../components/Navbar";
import Bubble from "../components/Bubble";
import {
  Drawer,
  List,
  ListItem,
  ListItemText,
  IconButton,
} from "@mui/material";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faBars } from "@fortawesome/free-solid-svg-icons";

const viewportHeight = window.innerHeight;

const HomePage = () => {
  const [drawerOpen, setDrawerOpen] = useState(false);

  const toggleDrawer = (open) => () => {
    setDrawerOpen(open);
  };

  const bubbles = Array.from({ length: 20 }).map((_, index) => (
    <Bubble key={index} />
  ));

  return (
    <div
      className="relative bg-cover bg-center overflow-hidden"
      style={{
        backgroundImage: `url(${process.env.PUBLIC_URL}/atlantis-background.png)`,
        height: viewportHeight,
      }}
    >
      {/* Drawer Button */}
      <div className="absolute top-4 left-4 z-50">
        <IconButton onClick={toggleDrawer(true)} style={{ color: "white" }}>
          <FontAwesomeIcon className={"text-sm text-white"} icon={faBars} />
        </IconButton>
      </div>

      {/* Drawer 內容 */}
      <Drawer
        anchor="left"
        open={drawerOpen}
        onClose={toggleDrawer(false)}
        PaperProps={{
          sx: {
            backgroundColor: "rgba(0, 0, 0, 0.6)", // 黑色半透明
            color: "white", // 文字顏色調整成白色比較清晰
            backdropFilter: "blur(5px)", // 類似毛玻璃效果 (可選)
          },
        }}
      >
        <div
          role="presentation"
          onClick={toggleDrawer(false)}
          onKeyDown={toggleDrawer(false)}
          style={{ width: 250 }}
        >
          <List>
            <ListItem button component={Link} to="/leaderboard">
              <ListItemText primary="排行榜" />
            </ListItem>
            <ListItem button component={Link} to="/members">
              <ListItemText primary="清冊" />
            </ListItem>
            <ListItem button component={Link} to="/monthlystats">
              <ListItemText primary="每月統計" />
            </ListItem>
          </List>
        </div>
      </Drawer>

      {/* 你的既有內容 */}
      {/* <Navbar /> */}
      <div className="absolute inset-0 bg-black bg-opacity-60 flex justify-center items-center text-center">
        <div className="text-white">
          <h1 className="text-4xl font-bold tracking-wider mb-2">亞特蘭提斯</h1>
          <h2 className="text-xl tracking-wide mt-0 mb-5">
            探索失落之城的神秘與美麗！
          </h2>
          <Link>
            <button
              className="w-full bg-yellow-500 text-white py-2 rounded transition duration-300 hover:bg-yellow-600"
              aria-label="开始探索"
            >
              功能開發中...
            </button>
          </Link>
          <h2 className="text-xs tracking-wide mt-2">＊建議用手機瀏覽體驗！</h2>
        </div>
      </div>

      {bubbles}
    </div>
  );
};

export default HomePage;
