import React from "react";
import styles from "./Bubble.module.css"; // 引入 CSS Module

const Bubble = () => {
  const size = Math.random() * (50 - 10) + 10; // 随机气泡大小
  const left = Math.random() * (100 - size / 2); // 减去一半的大小，避免超出边界
  const animationDuration = Math.random() * (5 - 2) + 2; // 随机动画时长
  const animationDelay = Math.random() * 3; // 随机延迟时间

  return (
    <div
      className={styles.bubble} // 应用 CSS Module 样式
      style={{
        width: `${size}px`,
        height: `${size}px`,
        left: `${left}vw`,
        bottom: "-10%",
        animationDuration: `${animationDuration}s`, // 设置动画时长
        animationDelay: `${animationDelay}s`, // 设置动画延迟
      }}
    />
  );
};

export default Bubble;
